#include "test_log_length.h"
#include <Monitor.h>
#include "../../../../../tf_common/tf_test_results.h"
#include "../../../../../tf_common/tf_uart_comms.h"
#include <stdio.h>


// Flag to ensure we only report the test result at most once
static asn1SccT_Boolean bResultReported = false;


// In the sister test TestLogLength we validate that the default log length allows less than 300 entries.
// In this test we want to validate that we successfully raised that level
#define MINUMUM_LOG_LENGTH       300


// Constructor
void test_log_length_startup(void)
{
    // Register the test that this TASTE Function will submit a result for
    testresult_register_test(TF_TEST_ID__TestLongerLog);
}


// Cyclic IF handler: sporadic_of (do nothing)
void test_log_length_PI_sporadic_if(void)
{
    asm volatile("nop");
}


// Cyclic IF handler: trigger_check
void test_log_length_PI_trigger_check( void )
{
    struct Monitor_InterfaceActivationEntry *aIfaLog;
    uint32_t iLastIndex;
    uint32_t nEntries;
    char aMsgBuff[100];

    // Only do this once
    if (bResultReported) {
        return;
    }

    // Halt the logging
    Monitor_FreezeInterfaceActivationLogging();

    // Load the activation log
    if (!Monitor_GetInterfaceActivationEntryLog(&aIfaLog, &iLastIndex, &nEntries)) {
        testresult_report_fail(TF_TEST_ID__TestLongerLog, "Failed to get log entries");
        bResultReported = true;
        return;
    }

    // Validate that this is not less than we expect
    if (nEntries < MINUMUM_LOG_LENGTH) {
        sprintf(aMsgBuff, "Log length is %d, which is below what is expected for the custom activation log length in this test", nEntries);
        testresult_report_fail(TF_TEST_ID__TestLongerLog, aMsgBuff);
        bResultReported = true;
        return;
    }

    // The activation log is a cyclic buffer: If we did not yet over-fill it then iLastIndex = nEntries - 1.  Validate we over-filled it
    if (iLastIndex == nEntries - 1) {
        sprintf(aMsgBuff, "Activation log seems to be not yet full: Last index (%d) still correlates to Size (%d)", iLastIndex, nEntries);
        testresult_report_fail(TF_TEST_ID__TestLongerLog, aMsgBuff);
        bResultReported = true;
        return;
    }

    // Report the log length
    sprintf(aMsgBuff, "Log length is now %d entries, and last index is %d", nEntries, iLastIndex);
    transmit_log_info(aMsgBuff);

    // Report the test as a pass
    testresult_report_pass(TF_TEST_ID__TestLongerLog);

    // Flag that we already did this
    bResultReported = true;
}


